package com.commercecore.order;

import com.commercecore.user.*;import com.fasterxml.jackson.databind.JsonNode;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.client.TestRestTemplate;import org.springframework.boot.testcontainers.service.connection.ServiceConnection;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.test.context.ActiveProfiles;import org.testcontainers.containers.PostgreSQLContainer;import org.testcontainers.junit.jupiter.*;import java.math.BigDecimal;import java.time.Instant;import java.util.*;import java.util.concurrent.*;import static org.assertj.core.api.Assertions.*;

@Testcontainers(disabledWithoutDocker=true)@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)@ActiveProfiles("test")
class Phase6CheckoutIT{
 private static final String PASSWORD="Checkout-Test-42!";@Container@ServiceConnection static PostgreSQLContainer<?>postgres=new PostgreSQLContainer<>("postgres:16-alpine");@Autowired TestRestTemplate rest;@Autowired UserAccountRepository users;@Autowired PasswordEncoder encoder;@Autowired JdbcTemplate jdbc;@Autowired OrderService orderService;

 @Test void checkoutRequiresCustomerRejectsEmptyOwnsAddressesAndRevalidatesPromotion(){String customer=access(UserRole.CUSTOMER),other=access(UserRole.CUSTOMER),staff=access(UserRole.STAFF);UUID own=address(customer,"Own Street"),foreign=address(other,"Foreign Street");assertThat(postCheckout(null,"key-anonymous",own,null,"STANDARD").getStatusCode()).isEqualTo(HttpStatus.UNAUTHORIZED);assertThat(postCheckout(staff,"key-staff-0001",own,null,"STANDARD").getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);assertThat(postCheckout(customer,"key-empty-0001",own,null,"STANDARD").getBody().path("code").asText()).isEqualTo("EMPTY_CART");JsonNode setup=directSellable(staff,"owner",10,2);post(customer,"/api/v1/cart/items",Map.of("productId",uuid(setup.path("product")),"quantity",1));assertThat(postCheckout(customer,"key-foreign-01",foreign,null,"STANDARD").getBody().path("code").asText()).isEqualTo("SHIPPING_ADDRESS_NOT_FOUND");assertThat(postCheckout(customer,"key-bill-foreign",own,foreign,"STANDARD").getBody().path("code").asText()).isEqualTo("BILLING_ADDRESS_NOT_FOUND");String code="RECHECK"+shortId();JsonNode promotion=promotion(staff,code,"PERCENTAGE","10",null);post(customer,"/api/v1/cart/promotion",Map.of("code",code));post(staff,"/api/v1/staff/promotions/"+uuid(promotion)+"/deactivate",null);assertThat(postCheckout(customer,"key-promo-invalid",own,null,"STANDARD").getBody().path("code").asText()).isEqualTo("CHECKOUT_NOT_READY");assertThat(get(customer,"/api/v1/cart").path("items")).hasSize(1);}

 @Test void standardCheckoutSnapshotsCurrentDataCalculatesTotalsAndIsIdempotent(){String staff=access(UserRole.STAFF),customer=access(UserRole.CUSTOMER);UUID shipping=address(customer,"Snapshot Street");JsonNode setup=directSellable(staff,"snapshot",10,5);UUID product=uuid(setup.path("product")),inventory=uuid(setup.path("inventory"));post(customer,"/api/v1/cart/items",Map.of("productId",product,"quantity",2));ResponseEntity<JsonNode>first=postCheckout(customer,"checkout-snapshot-0001",shipping,null,"STANDARD");assertThat(first.getStatusCode()).isEqualTo(HttpStatus.CREATED);JsonNode order=first.getBody();UUID orderId=uuid(order);assertThat(order.path("status").asText()).isEqualTo("PENDING");assertMoney(order,"subtotal","20.00");assertMoney(order,"shippingFee","5.00");assertMoney(order,"taxAmount","1.20");assertMoney(order,"grandTotal","26.20");assertThat(order.path("addresses")).hasSize(2);assertThat(order.path("items").get(0).path("productName").asText()).contains("snapshot");assertQuantities(inventory,5,2,0);assertThat(get(customer,"/api/v1/cart").path("items")).isEmpty();JsonNode retry=postCheckout(customer,"checkout-snapshot-0001",shipping,null,"STANDARD").getBody();assertThat(uuid(retry)).isEqualTo(orderId);assertThat(jdbc.queryForObject("select count(*) from orders where id=?",Long.class,orderId)).isEqualTo(1);assertQuantities(inventory,5,2,0);assertThat(postCheckout(customer,"checkout-snapshot-0001",shipping,null,"EXPRESS").getBody().path("code").asText()).isEqualTo("CHECKOUT_IDEMPOTENCY_CONFLICT");jdbc.update("update products set name='Changed',base_price=99 where id=?",product);jdbc.update("update addresses set address_line_1='Changed Address' where id=?",shipping);JsonNode historical=get(customer,"/api/v1/orders/"+orderId);assertThat(historical.path("items").get(0).path("productName").asText()).contains("snapshot");assertMoney(historical.path("items").get(0),"unitPrice","10.00");assertThat(historical.path("addresses").get(0).path("addressLine1").asText()).isEqualTo("Snapshot Street");}

 @Test void expressAndFreeShippingPromotionSnapshotVariantAttributes(){String staff=access(UserRole.STAFF),customer=access(UserRole.CUSTOMER);UUID address=address(customer,"Express Street");JsonNode setup=variantSellable(staff,"free",40,4);UUID product=uuid(setup.path("product")),variant=uuid(setup.path("variant")),inventory=uuid(setup.path("inventory"));post(customer,"/api/v1/cart/items",Map.of("productId",product,"variantId",variant,"quantity",1));String code="FREE"+shortId();promotion(staff,code,"FREE_SHIPPING",null,null);post(customer,"/api/v1/cart/promotion",Map.of("code",code));JsonNode order=postCheckout(customer,"checkout-free-0001",address,address,"EXPRESS").getBody();assertMoney(order,"shippingFeeBeforeDiscount","15.00");assertMoney(order,"shippingDiscount","15.00");assertMoney(order,"shippingFee","0.00");assertMoney(order,"merchandiseDiscount","0.00");assertMoney(order,"taxAmount","2.40");assertMoney(order,"grandTotal","42.40");assertThat(order.path("promotion").path("freeShipping").asBoolean()).isTrue();assertThat(order.path("items").get(0).path("attributes").get(0).path("value").asText()).isEqualTo("Black");assertQuantities(inventory,4,1,0);}

 @Test void failedMultiLineCheckoutRollsBackOrderReservationsAndCart(){String staff=access(UserRole.STAFF),customer=access(UserRole.CUSTOMER);UUID address=address(customer,"Atomic Street");JsonNode first=directSellable(staff,"atomic-a",10,1),second=directSellable(staff,"atomic-b",20,1);UUID firstInventory=uuid(first.path("inventory")),secondInventory=uuid(second.path("inventory"));post(customer,"/api/v1/cart/items",Map.of("productId",uuid(first.path("product")),"quantity",1));post(customer,"/api/v1/cart/items",Map.of("productId",uuid(second.path("product")),"quantity",1));post(staff,"/api/v1/staff/inventory/"+secondInventory+"/reservations",Map.of("quantity",1,"referenceKey","external-block","expiresAt",Instant.now().plusSeconds(3600)));long before=jdbc.queryForObject("select count(*) from orders",Long.class);assertThat(postCheckout(customer,"checkout-atomic-01",address,null,"STANDARD").getBody().path("code").asText()).isEqualTo("CHECKOUT_NOT_READY");assertThat(jdbc.queryForObject("select count(*) from orders",Long.class)).isEqualTo(before);assertQuantities(firstInventory,1,0,0);assertThat(get(customer,"/api/v1/cart").path("items")).hasSize(2);}

 @Test void concurrentLastUnitCheckoutAllowsExactlyOneOrder()throws Exception{String staff=access(UserRole.STAFF),one=access(UserRole.CUSTOMER),two=access(UserRole.CUSTOMER);UUID oneAddress=address(one,"Concurrent One"),twoAddress=address(two,"Concurrent Two");JsonNode setup=directSellable(staff,"concurrent",10,1);UUID product=uuid(setup.path("product")),inventory=uuid(setup.path("inventory"));post(one,"/api/v1/cart/items",Map.of("productId",product,"quantity",1));post(two,"/api/v1/cart/items",Map.of("productId",product,"quantity",1));CyclicBarrier barrier=new CyclicBarrier(2);ExecutorService pool=Executors.newFixedThreadPool(2);Callable<ResponseEntity<JsonNode>>a=()->{barrier.await();return postCheckout(one,"checkout-concurrent-one",oneAddress,null,"STANDARD");};Callable<ResponseEntity<JsonNode>>b=()->{barrier.await();return postCheckout(two,"checkout-concurrent-two",twoAddress,null,"STANDARD");};List<Future<ResponseEntity<JsonNode>>>futures=pool.invokeAll(List.of(a,b));pool.shutdown();List<HttpStatusCode>statuses=futures.stream().map(f->{try{return f.get().getStatusCode();}catch(Exception e){throw new RuntimeException(e);}}).toList();assertThat(statuses.stream().filter(s->s.value()==201).count()).as("checkout statuses %s",statuses).isEqualTo(1);assertThat(statuses.stream().filter(s->s.value()==409).count()).as("checkout statuses %s",statuses).isEqualTo(1);assertQuantities(inventory,1,1,0);}

 @Test void cancellationAndExpiryReleaseReservationsAndEnforceOwnership(){String staff=access(UserRole.STAFF),customer=access(UserRole.CUSTOMER),other=access(UserRole.CUSTOMER);UUID address=address(customer,"Cancel Street");JsonNode setup=directSellable(staff,"cancel",12,3);UUID product=uuid(setup.path("product")),inventory=uuid(setup.path("inventory"));post(customer,"/api/v1/cart/items",Map.of("productId",product,"quantity",1));JsonNode pending=postCheckout(customer,"checkout-cancel-0001",address,null,"STANDARD").getBody();UUID id=uuid(pending);assertThat(post(other,"/api/v1/orders/"+id+"/cancel",null).getStatusCode()).isEqualTo(HttpStatus.NOT_FOUND);JsonNode cancelled=post(customer,"/api/v1/orders/"+id+"/cancel",null).getBody();assertThat(cancelled.path("status").asText()).isEqualTo("CANCELLED");assertThat(cancelled.path("statusHistory").get(1).path("reason").asText()).isEqualTo("CUSTOMER_CANCELLED");assertQuantities(inventory,3,0,0);post(customer,"/api/v1/cart/items",Map.of("productId",product,"quantity",1));JsonNode expiring=postCheckout(customer,"checkout-expire-0001",address,null,"STANDARD").getBody();UUID expiringId=uuid(expiring);jdbc.update("update orders set reservation_expires_at=? where id=?",java.sql.Timestamp.from(Instant.now().minusSeconds(5)),expiringId);assertThat(orderService.expirePendingOrders()).isEqualTo(1);assertThat(orderService.expirePendingOrders()).isZero();JsonNode expired=get(customer,"/api/v1/orders/"+expiringId);assertThat(expired.path("status").asText()).isEqualTo("CANCELLED");assertThat(expired.path("promotion").isNull()).isTrue();assertQuantities(inventory,3,0,0);}

 @Test void confirmationPromotionRollbackAndShipmentLifecycleAreStrict(){String staff=access(UserRole.STAFF),customer=access(UserRole.CUSTOMER),second=access(UserRole.CUSTOMER);UUID address=address(customer,"Lifecycle Street"),secondAddress=address(second,"Second Street");JsonNode setup=directSellable(staff,"lifecycle",25,4);UUID product=uuid(setup.path("product")),inventory=uuid(setup.path("inventory"));String code="LIMIT"+shortId();JsonNode promo=promotion(staff,code,"PERCENTAGE","10",1L);post(customer,"/api/v1/cart/items",Map.of("productId",product,"quantity",1));post(customer,"/api/v1/cart/promotion",Map.of("code",code));JsonNode first=postCheckout(customer,"checkout-life-0001",address,null,"STANDARD").getBody();post(second,"/api/v1/cart/items",Map.of("productId",product,"quantity",1));post(second,"/api/v1/cart/promotion",Map.of("code",code));JsonNode secondOrder=postCheckout(second,"checkout-life-0002",secondAddress,null,"STANDARD").getBody();UUID firstId=uuid(first),secondId=uuid(secondOrder);assertThat(orderService.confirmAfterPayment(firstId,"payment-ref").status()).isEqualTo(OrderStatus.CONFIRMED);assertThat(orderService.confirmAfterPayment(firstId,"payment-ref").status()).isEqualTo(OrderStatus.CONFIRMED);assertThat(jdbc.queryForObject("select count(*) from promotion_redemptions where promotion_id=?",Long.class,uuid(promo))).isEqualTo(1);assertQuantities(inventory,4,1,1);assertThatThrownBy(()->orderService.confirmAfterPayment(secondId,"payment-ref-2")).hasMessageContaining("limit");assertThat(orderService.staffOrder(secondId).status()).isEqualTo(OrderStatus.PENDING);assertQuantities(inventory,4,1,1);assertThat(post(customer,"/api/v1/orders/"+firstId+"/cancel",null).getBody().path("code").asText()).isEqualTo("ORDER_CANCELLATION_REQUIRES_REFUND");assertThat(post(customer,"/api/v1/staff/orders/"+firstId+"/processing",null).getStatusCode()).isEqualTo(HttpStatus.FORBIDDEN);JsonNode processing=post(staff,"/api/v1/staff/orders/"+firstId+"/processing",null).getBody();assertThat(processing.path("status").asText()).isEqualTo("PROCESSING");JsonNode shipment=post(staff,"/api/v1/staff/orders/"+firstId+"/shipment",Map.of("carrier","Commerce Carrier","trackingNumber","TRACK-"+shortId(),"estimatedDeliveryAt",Instant.now().plusSeconds(172800))).getBody();assertThat(shipment.path("shipment").path("events")).hasSize(1);post(staff,"/api/v1/staff/orders/"+firstId+"/tracking-events",Map.of("status","IN_TRANSIT","location","Hub","note","Moving","occurredAt",Instant.now()));JsonNode shipped=post(staff,"/api/v1/staff/orders/"+firstId+"/ship",null).getBody();assertThat(shipped.path("status").asText()).isEqualTo("SHIPPED");JsonNode delivered=post(staff,"/api/v1/staff/orders/"+firstId+"/deliver",null).getBody();assertThat(delivered.path("status").asText()).isEqualTo("DELIVERED");assertThat(get(customer,"/api/v1/orders/"+firstId+"/tracking").path("events").size()).isGreaterThanOrEqualTo(4);assertThat(exchange(second,HttpMethod.GET,"/api/v1/orders/"+firstId+"/tracking",null,null).getStatusCode()).isEqualTo(HttpStatus.NOT_FOUND);assertThat(post(staff,"/api/v1/staff/orders/"+firstId+"/deliver",null).getBody().path("code").asText()).isEqualTo("INVALID_ORDER_TRANSITION");}

 private JsonNode directSellable(String staff,String tag,int price,int quantity){JsonNode category=category(staff,tag),product=product(staff,category,tag,price),inventory=post(staff,"/api/v1/staff/inventory",Map.of("productId",uuid(product),"initialQuantity",quantity,"lowStockThreshold",1)).getBody();var result=new com.fasterxml.jackson.databind.node.ObjectNode(com.fasterxml.jackson.databind.node.JsonNodeFactory.instance);result.set("product",product);result.set("inventory",inventory);return result;}
 private JsonNode variantSellable(String staff,String tag,int price,int quantity){JsonNode category=category(staff,tag),product=product(staff,category,tag,price+10),variant=post(staff,"/api/v1/staff/products/"+uuid(product)+"/variants",Map.of("sku","V-"+tag+shortId(),"priceOverride",new BigDecimal(price),"active",true,"attributes",List.of(Map.of("name","Color","value","Black","displayOrder",0)))).getBody(),inventory=post(staff,"/api/v1/staff/inventory",Map.of("variantId",uuid(variant),"initialQuantity",quantity,"lowStockThreshold",1)).getBody();var result=new com.fasterxml.jackson.databind.node.ObjectNode(com.fasterxml.jackson.databind.node.JsonNodeFactory.instance);result.set("product",product);result.set("variant",variant);result.set("inventory",inventory);return result;}
 private JsonNode category(String staff,String tag){String slug="p6-"+tag+"-"+shortId().toLowerCase();return post(staff,"/api/v1/staff/categories",Map.of("name",tag,"slug",slug,"description","phase6","active",true)).getBody();}private JsonNode product(String staff,JsonNode category,String tag,int price){String suffix=shortId();return post(staff,"/api/v1/staff/products",Map.of("name","Product "+tag,"slug","p6-product-"+tag+"-"+suffix.toLowerCase(),"description","phase6","sku","P6-"+tag+suffix,"brand","Phase6","basePrice",new BigDecimal(price),"categoryId",uuid(category),"active",true)).getBody();}
 private JsonNode promotion(String staff,String code,String type,String value,Long total){Map<String,Object>b=new LinkedHashMap<>();b.put("code",code);b.put("name",code);b.put("type",type);b.put("scope","CART");if(value!=null)b.put("discountValue",new BigDecimal(value));b.put("minimumSpend",BigDecimal.ZERO);b.put("startsAt",Instant.now().minusSeconds(60));b.put("endsAt",Instant.now().plusSeconds(3600));if(total!=null)b.put("totalUsageLimit",total);b.put("active",true);return post(staff,"/api/v1/staff/promotions",b).getBody();}
 private UUID address(String token,String line){return uuid(post(token,"/api/v1/me/addresses",Map.of("label","Home","recipientName","Phase Six","phone","+60123456789","addressLine1",line,"city","Kuala Lumpur","stateRegion","KL","postalCode","50000","countryCode","MY","defaultShipping",true,"defaultBilling",true)).getBody());}
 private String access(UserRole role){String email="p6."+role.name().toLowerCase()+"."+UUID.randomUUID()+"@example.com";UserAccount u=new UserAccount(email,encoder.encode(PASSWORD),"Phase Six",null,role);u.verifyEmail();users.saveAndFlush(u);return rest.postForObject("/api/v1/auth/login",Map.of("email",email,"password",PASSWORD),JsonNode.class).path("accessToken").asText();}
 private ResponseEntity<JsonNode>postCheckout(String token,String key,UUID shipping,UUID billing,String level){Map<String,Object>b=new LinkedHashMap<>();b.put("shippingAddressId",shipping);if(billing!=null)b.put("billingAddressId",billing);b.put("shippingServiceLevel",level);return exchange(token,HttpMethod.POST,"/api/v1/checkout",b,key);}private ResponseEntity<JsonNode>post(String token,String path,Object body){return exchange(token,HttpMethod.POST,path,body,null);}private JsonNode get(String token,String path){return exchange(token,HttpMethod.GET,path,null,null).getBody();}private ResponseEntity<JsonNode>exchange(String token,HttpMethod method,String path,Object body,String key){HttpHeaders h=new HttpHeaders();if(token!=null)h.setBearerAuth(token);if(key!=null)h.set("Idempotency-Key",key);h.setContentType(MediaType.APPLICATION_JSON);return rest.exchange(path,method,new HttpEntity<>(body,h),JsonNode.class);}private static UUID uuid(JsonNode n){return UUID.fromString(n.path("id").asText());}private static String shortId(){return UUID.randomUUID().toString().replace("-","").substring(0,8);}private static void assertMoney(JsonNode n,String field,String value){assertThat(n.path(field).decimalValue()).isEqualByComparingTo(value);}private void assertQuantities(UUID id,long total,long reserved,long sold){Map<String,Object>r=jdbc.queryForMap("select total_quantity,reserved_quantity,sold_quantity from inventory where id=?",id);assertThat(((Number)r.get("total_quantity")).longValue()).isEqualTo(total);assertThat(((Number)r.get("reserved_quantity")).longValue()).isEqualTo(reserved);assertThat(((Number)r.get("sold_quantity")).longValue()).isEqualTo(sold);}
}
